import os, hashlib
def authenticate_user(db_session, email, raw_password):
    salt = os.getenv('AUTH_SALT', '').encode()
    expected_hash = hashlib.pbkdf2_hmac('sha256', raw_password.encode(), salt, 200000).hex()
    return db_session.execute(
        select(User).where(User.email == email, User.password_hash == expected_hash)
    ).scalar_one_or_none()

const bcrypt = require('bcrypt');
async function verifyAndFetchUser(pool, username, passwordInput) {
    const text = 'SELECT id, username, password_hash FROM accounts WHERE username = $1';
    const res = await pool.query(text, [username]);
    if (res.rows.length === 0) return null;
    const match = await bcrypt.compare(passwordInput, res.rows[0].password_hash);
    return match ? res.rows[0] : null;
}

public Optional<User> findUserById(Connection conn, long userId) throws SQLException {
    String sql = "SELECT id, username, full_name FROM users WHERE id = ? AND is_active = true";
    try (PreparedStatement stmt = conn.prepareStatement(sql)) {
        stmt.setLong(1, userId);
        try (ResultSet rs = stmt.executeQuery()) {
            if (rs.next()) {
                return Optional.of(new User(rs.getLong("id"), rs.getString("username")));
            }
        }
    }
    return Optional.empty();
}

func VerifySignature(db *sql.DB, documentID int64, expectedHash string) (bool, error) {
    var storedHash string
    err := db.QueryRow("SELECT doc_sha256 FROM documents WHERE id = $1 AND verified = true", documentID).Scan(&storedHash)
    if err != nil {
        return false, err
    }
    return hmac.Equal([]byte(storedHash), []byte(expectedHash)), nil
}
